# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SCHOOL SUBJECTS &amp; WEEKLY TIMETABLE (DERS PROGRAMI)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">School Subjects (Okul Dersleri)</text>\n  <text x="180" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Maths (Matematik) • Science (Fen Bilimleri)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Turkish (Türkçe) • Social Studies (Sosyal B.)</text>\n  <text x="180" y="145" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• English / Foreign Language (İngilizce / Y. Dil)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Religion and Morals (Din Kültürü ve A. B.)</text>\n  <text x="180" y="195" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• P.E. (Physical Education) • IT (Bilişim)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Art (Görsel Sanatlar) • Music • Drama</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Days &amp; Timetable Vocabulary</text>\n  <text x="520" y="95" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Weekdays: Monday, Tuesday, Wednesday, Thursday, Friday</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Weekend: Saturday, Sunday</text>\n  <text x="520" y="145" text-anchor="middle" font-size="12" fill="#0f172a">• a timetable (ders programı) • a break (teneffüs)</text>\n  <text x="520" y="168" text-anchor="middle" font-size="12" fill="#0f172a">• double lessons (blok/çift ders) • lunch (öğle yemeği)</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">«We have got double Science lessons on Tuesday.»</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#334155">to start (başlamak) ⇄ to finish (bitmek)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CLASSROOM OBJECTS, THERE IS / ARE &amp; OBJECT PRONOUNS</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Classroom Objects &amp; There is / There are</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• smartboard (akıllı tahta) • board marker (tahta kalemi)</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• bookshelf (kitaplık) • dictionary (sözlük) • sheet (kağıt)</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• rubber / eraser (silgi) • rubbish bin (çöp kutusu)</text>\n  <text x="180" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• pencil case (kalemlik) • desk / seat (sıra / oturak)</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">There is a smartboard in our classroom. (Tekil)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">There are twenty-five seats in the class. (Çoğul)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Object Pronouns &amp; Classroom Rules</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">I ➔ me | you ➔ you | he ➔ him | she ➔ her</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">it ➔ it | we ➔ us | they ➔ them</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11" fill="#0f172a">• Can you lend me your dictionary? (Bana ödünç verir misin?)</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" fill="#0f172a">• Raise your hand and listen carefully! (Elini kaldır...)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" fill="#0f172a">• Tidy up your desk and don\'t shout! (Sıranı topla...)</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Adverbs: quietly, loudly, carefully, slowly</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ASKING ABOUT TIME &amp; PRESENT SIMPLE ROUTINES</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Asking About Lesson Times (What time...?)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">Q: What time does the Maths class start?</text>\n  <text x="180" y="118" text-anchor="middle" font-size="12" fill="#0f172a">A: It starts at quarter past nine (09:15).</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">Q: What time do you have lunch on weekdays?</text>\n  <text x="180" y="170" text-anchor="middle" font-size="12" fill="#0f172a">A: We have lunch at half past twelve (12:30).</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Prepositions: ON Monday | AT 8 o\'clock | IN the morning</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#475569">Numbers 50-100: fifty, sixty, seventy, eighty, ninety, one hundred</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Target Social Language (Günlük Deyimler)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Make the grade! (Başarılı ol / Sınıfı geç!)</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Don\'t skip the lesson! / Don\'t cut the class!</text>\n  <text x="520" y="142" text-anchor="middle" font-size="10" fill="#475569">(Dersi kaçırma / Dersi asma!)</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Give me a hand for this homework! (Bana yardım et!)</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• I don\'t feel all right. (Kendimi iyi hissetmiyorum.)</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">• I\'d love to! (Çok isterim / Memnuniyetle!)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
